const languagesMessageResults = `-- name: LanguagesMessageResults :many
WITH unsub AS (
    SELECT DISTINCT e.message_id FROM delivery_events e
    WHERE e.campaign_id = $1 AND e.type = 'unsubscribe' AND e.message_id IS NOT NULL
)
SELECT m.language, m.language_reason, m.contact_language,
       count(*) FILTER (WHERE m.sent_at IS NOT NULL)::bigint AS sent,
       count(*) FILTER (WHERE m.delivered_at IS NOT NULL OR m.status = 'complained')::bigint AS delivered,
       count(*) FILTER (WHERE m.human_opened_at IS NOT NULL)::bigint AS human_opens,
       count(*) FILTER (WHERE m.clicked_at IS NOT NULL)::bigint AS clicks,
       count(*) FILTER (WHERE m.status = 'complained')::bigint AS complaints,
       count(*) FILTER (WHERE unsub.message_id IS NOT NULL)::bigint AS unsubscribes
FROM messages m
LEFT JOIN unsub ON unsub.message_id = m.id
WHERE m.campaign_id = $1 AND m.status <> 'cancelled'
GROUP BY 1, 2, 3
`

type LanguagesMessageResultsRow struct {
	Language        string `json:"language"`
	LanguageReason  string `json:"languageReason"`
	ContactLanguage string `json:"contactLanguage"`
	Sent            int64  `json:"sent"`
	Delivered       int64  `json:"delivered"`
	HumanOpens      int64  `json:"humanOpens"`
	Clicks          int64  `json:"clicks"`
	Complaints      int64  `json:"complaints"`
	Unsubscribes    int64  `json:"unsubscribes"`
}

// Results of a sent campaign per language version and why readers got it.
func (q *Queries) LanguagesMessageResults(ctx context.Context, campaignID *uuid.UUID) ([]LanguagesMessageResultsRow, error) {
	rows, err := q.db.Query(ctx, languagesMessageResults, campaignID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LanguagesMessageResultsRow{}
	for rows.Next() {
		var i LanguagesMessageResultsRow
		if err := rows.Scan(
			&i.Language,
			&i.LanguageReason,
			&i.ContactLanguage,
			&i.Sent,
			&i.Delivered,
			&i.HumanOpens,
			&i.Clicks,
			&i.Complaints,
			&i.Unsubscribes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const languagesPreviewContacts = `-- name: LanguagesPreviewContacts :many
SELECT DISTINCT ON (lower(split_part(replace(c.language, '_', '-'), '-', 1)))
       c.id, c.email, c.first_name, c.last_name, c.language
FROM contacts c
WHERE c.workspace_id = $1 AND c.erased_at IS NULL AND c.status = 'active' AND c.language <> ''
  AND (cardinality($2::uuid[]) = 0 OR EXISTS (
    SELECT 1 FROM list_memberships m
    WHERE m.contact_id = c.id AND m.status = 'subscribed'
      AND m.list_id = ANY(ARRAY(SELECT ll.id FROM lists ll WHERE ll.id = ANY($2::uuid[]) AND ll.deleted_at IS NULL))))
ORDER BY lower(split_part(replace(c.language, '_', '-'), '-', 1)), (c.first_name = '') ASC, c.last_open_at DESC NULLS LAST, c.email
LIMIT 200
`

type LanguagesPreviewContactsParams struct {
	WorkspaceID uuid.UUID   `json:"workspaceId"`
	Lists       []uuid.UUID `json:"lists"`
}

type LanguagesPreviewContactsRow struct {
	ID        uuid.UUID `json:"id"`
	Email     string    `json:"email"`
	FirstName string    `json:"firstName"`
	LastName  string    `json:"lastName"`
	Language  string    `json:"language"`
}

// "Preview as" in the composer: one active contact per contact language
// (its base code), from the given lists when there are any, people with a
// first name first.
func (q *Queries) LanguagesPreviewContacts(ctx context.Context, arg LanguagesPreviewContactsParams) ([]LanguagesPreviewContactsRow, error) {
	rows, err := q.db.Query(ctx, languagesPreviewContacts, arg.WorkspaceID, arg.Lists)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LanguagesPreviewContactsRow{}
	for rows.Next() {
		var i LanguagesPreviewContactsRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.FirstName,
			&i.LastName,
			&i.Language,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

